<script setup lang="ts">
import {ref,computed,watch,defineAsyncComponent} from 'vue'
import {useStudio,id} from '../studioContext'
const ClueGraph=defineAsyncComponent(()=>import('../ClueGraph.vue'))
import {clueForest,canReparent} from '../treeRuntime'
import RelationshipGraph from '../RelationshipGraph.vue'
import {narrativeText,setNarrativeText,narrativeLocked} from '../narrative'
import EntityActions from '../EntityActions.vue'
import ReviewUnit from '../ReviewUnit.vue'
import ReviewBadge from '../ReviewBadge.vue'
import AppIcon from '../AppIcon.vue'
import SmartEditButton from '../SmartEditButton.vue'
import SmartEditBatch from '../SmartEditBatch.vue'
const picking=ref<any>(null)
const s=useStudio(),selected=ref(''),folder=ref<any>(null),folderName=ref(''),folderParent=ref('')
const clues=computed(()=>s.entries('clue')),r=computed(()=>clues.value.find((r:any)=>r.id===selected.value)||clues.value[0]),roots=computed(()=>s.p.value.workspace.folders.filter((f:any)=>f.root)),labels:any={culture:'文化背景',relationship:'人物关系',narrative:'叙事线索'}
function add(){const c=s.add('clue',{name:'新线索',type:'culture',parentId:'culture',summary:'',plotIds:[],characterIds:[],units:[]});selected.value=c.id}
function unit(){r.value.draft.units.push({id:id(),text:'',kind:'event',category:'fiction',speakerId:'',rationale:'',references:[]})}
async function moveNode(source:string,target:string){
 if(source.startsWith('c:')&&s.locked('clue',source.slice(2),'parentId')||source.startsWith('f:')&&s.rootLocked('/workspace/folders',true))throw Error('此分类区域正在生成，请结束后再移动')
 if(!canReparent(clueForest(s.p.value.workspace.folders,clues.value),source,target))throw Error('只能移入同类分类，且不能形成循环')
 await s.saveAll()
 if(source.startsWith('f:')){const fs=JSON.parse(JSON.stringify(s.p.value.workspace.folders));fs.find((f:any)=>f.id===source.slice(2)).parentId=target.slice(2);const result=await s.api(`/projects/${s.p.value.id}/studio/folders`,'PUT',{version:s.p.value.version,folders:fs});await s.legacy(result)}
 else{const row=s.rec('clue',source.slice(2));const result=await s.api(`/projects/${s.p.value.id}/studio/units/workspace`,'PATCH',{version:s.p.value.version,requestId:crypto.randomUUID(),changes:[{path:'/workspace/entities/clue:'+row.id+'/draft/parentId',before:row.draft.parentId,value:target.slice(2)}]});await s.legacy(result)}
}
async function moveSafely(source:string,target:string){try{await moveNode(source,target)}catch(e:any){s.error.value=e.message}}
async function destination(target:string){if(!picking.value)return;if(picking.value.kind==='folder-form')folderParent.value=target;else await moveSafely(picking.value.id,'f:'+target);picking.value=null}

function ownerChanged(){const owner=r.value.draft.plotIds[0];r.value.draft.characterIds=[...(s.rec('plot',owner)?.draft.characterIds||[])]}
async function unlockNarrative(){for(const u of r.value.draft.units||[])u.locked=false;await s.run(s.saveAll)}
function reference(u:any){u.references.push({sourceId:'',sourceVersion:1,annotationId:'',quote:''})}
function bind(ref:any){ref.sourceVersion=(s.rec('material','main').published?.sources||s.p.value.sources).find((s:any)=>s.id===ref.sourceId)?.version||1;ref.annotationId=''}
function editFolder(f:any){const original=s.p.value.workspace.folders.find((v:any)=>'f:'+v.id===f.id||v.id===f.id);folder.value=original;folderName.value=original.name;folderParent.value=original.parentId}
async function createFolder(){const fs=JSON.parse(JSON.stringify(s.p.value.workspace.folders));const parent=folder.value||roots.value[0];fs.push({id:id(),name:folderName.value||'新分类',parentId:parent.id,type:parent.type,root:false});await s.saveFolders(fs);folder.value=null}
async function updateFolder(remove=false){const fs=JSON.parse(JSON.stringify(s.p.value.workspace.folders));const f=fs.find((f:any)=>f.id===folder.value.id);if(remove){if(fs.some((n:any)=>n.parentId===f.id)){s.error.value='请先移动或删除子分类';return}fs.splice(fs.indexOf(f),1)}else{f.name=folderName.value;f.parentId=folderParent.value}await s.saveFolders(fs);folder.value=null}
watch(()=>s.focus.value,(v:string)=>{if(v.startsWith('clue:'))selected.value=v.split(':')[1]},{immediate:true})
</script>
<template><ReviewUnit unit-id="clues:main" label="确认线索库"/><details class="clue-graph"><summary>人物关系图</summary><RelationshipGraph :people="s.rec('material','main')?.draft.structured?.people||[]" :relations="s.rec('material','main')?.draft.structured?.relations||[]" :evidence="s.rec('material','main')?.draft.structured?.evidence||[]" :published-relations="s.rec('material','main')?.published?.structured?.relations||[]"/></details><SmartEditBatch kind="clue" :rows="clues" label="线索"/><div class="clue-editor-layout"><div class="clue-tree-area"><div class="rail-heading"><h2>线索层级</h2><button @click="add">＋ 线索</button></div><div class="tree-legend"><span>实线：有依据</span><span>虚线：推测</span><span>无框：虚构</span></div><ClueGraph :folders="s.p.value.workspace.folders" :clues="clues" :selected="r?.id||''" :move-node="moveSafely" @select="s.selectEntity('clue',$event)" @folder="editFolder"/></div><article v-if="r" :data-entity-key="'clue:'+r.id"><fieldset :disabled="s.locked('clue',r.id)"><div class="rail-heading"><h2>{{r.draft.name}}</h2><SmartEditButton kind="clue" :item-ids="[r.id]" :label="r.draft.name"/></div><label>线索名称<input v-model="r.draft.name"></label><div class="actions"><small>所在分类：{{s.p.value.workspace.folders.find((f:any)=>f.id===r.draft.parentId)?.name||'分类待整理'}}</small><button @click="picking={id:'c:'+r.id}">移动到分类</button></div><template v-if="r.draft.type==='narrative'"><label>所属剧情<select :value="r.draft.plotIds.length===1?r.draft.plotIds[0]:''" @change="r.draft.plotIds=[($event.target as HTMLSelectElement).value];ownerChanged()"><option value="">选择唯一所属剧情</option><option v-for="p in s.entries('plot')" :value="p.id">{{p.draft.title}}</option></select></label><small v-if="r.draft.plotIds.length>1">旧线索关联了多个剧情，请选择唯一所属剧情后保存。</small><small v-if="r.draft.content===undefined&&r.draft.units?.length>1">旧版内容已合并显示，可编辑为一小段情节；原内容与依据仍保留。</small><label>情节内容<textarea rows="6" :value="narrativeText(r.draft)" :disabled="narrativeLocked(r.draft)" @input="setNarrativeText(r.draft,($event.target as HTMLTextAreaElement).value)" placeholder="用一小段文字描述这条线索中的情节。"/></label><div v-if="narrativeLocked(r.draft)" class="actions"><small>情节已锁定。</small><button @click="unlockNarrative">解锁情节并保存</button></div><small>每条叙事线索只属于一个剧情。编辑后的情节按叙事创作保存，不自动作为史料原文。</small><details v-if="r.draft.units?.some((u:any)=>u.references?.length)||r.draft.legacyUnits?.length" class="narrative-evidence"><summary>查看原有内容与依据</summary><p v-for="u in r.draft.legacyUnits||r.draft.units">{{u.text}}<small v-for="ref in u.references">{{ref.quote}}</small></p></details></template><template v-else><label>概述<textarea v-model="r.draft.summary"/></label><fieldset><legend>关联人物</legend><label v-for="c in s.castEntries()"><input type="checkbox" :value="c.id" v-model="r.draft.characterIds">{{c.draft.name}}</label></fieldset><details v-if="r.draft.type==='relationship'"><summary>编辑方向关系</summary><p class="muted">甲 → 关系名称 → 乙；引用必须逐字来自已确认资料。</p><div v-for="(edge,ei) in r.draft.relations||[]" class="card"><label>甲<select v-model="edge.fromId"><option v-for="c in s.castEntries()" :value="c.id">{{c.draft.name}}</option></select></label><label>关系名称<input v-model="edge.label"/></label><label>乙<select v-model="edge.toId"><option v-for="c in s.castEntries()" :value="c.id">{{c.draft.name}}</option></select></label><label>来源<select v-model="edge.sourceId" @change="edge.sourceVersion=(s.rec('material','main').published?.sources||[]).find((v:any)=>v.id===edge.sourceId)?.version||1"><option v-for="source in s.rec('material','main').published?.sources||[]" :value="source.id">{{source.title}}</option></select></label><label>逐字引文<textarea v-model="edge.quote"/></label><button @click="r.draft.relations.splice(Number(ei),1)">移除此方向关系</button></div><button @click="(r.draft.relations||=[]).push({fromId:'',toId:'',label:'',sourceId:'',sourceVersion:1,quote:''})">添加方向关系</button></details><details><summary>高级：细分内容与逐字依据</summary><div v-for="(u,i) in r.draft.units" class="card"><div class="actions"><b>单元 {{Number(i)+1}}</b><SmartEditButton kind="clue" :item-ids="[r.id]" :unit-ids="[u.id]" :fields="['text','rationale']" :label="r.draft.name+' · 单元 '+(Number(i)+1)"/><button @click="u.locked=!u.locked;s.run(s.saveAll)">{{u.locked?'解锁':'锁定'}}</button><button :disabled="u.locked" @click="r.draft.units.splice(Number(i),1)">删除单元</button></div><fieldset :disabled="u.locked"><textarea rows="4" v-model="u.text"/><div class="compact-grid"><label>类型<select v-model="u.kind"><option value="event">事件</option><option value="action">动作</option><option value="dialogue">对白</option><option value="clue">信息</option></select></label><label>真实性<select v-model="u.category"><option value="supported">有依据</option><option value="inference">解释／推测</option><option value="fiction">合理虚构</option></select></label></div><label v-if="u.kind==='dialogue'">说话人物<select v-model="u.speakerId"><option value="">无</option><option v-for="c in s.castEntries()" :value="c.id">{{c.draft.name}}</option></select></label><label>推导／虚构用途<textarea v-model="u.rationale"/></label><div v-for="ref in u.references" class="reference-row"><select v-model="ref.sourceId" @change="bind(ref)"><option value="">选择资料或画面观察</option><option v-for="source in s.rec('material','main').published?.sources||s.p.value.sources" :value="source.id">{{source.title}}</option></select><select v-if="!ref.sourceId" v-model="ref.annotationId" @change="ref.quote=(s.rec('material','main').published?.annotations||[]).find((a:any)=>a.id===ref.annotationId)?.description||''"><option value="">选择已确认画面观察</option><option v-for="a in (s.rec('material','main').published?.annotations||[]).filter((a:any)=>a.confirmed)" :value="a.id">{{a.description}}</option></select><textarea v-model="ref.quote" placeholder="逐字引用原文"/><details v-if="ref.sourceId"><summary>原文</summary><p class="pre">{{(s.rec('material','main').published?.sources||s.p.value.sources).find((v:any)=>v.id===ref.sourceId)?.text}}</p></details><button @click="u.references=u.references.filter((v:any)=>v!==ref)">移除引用</button></div><button @click="reference(u)">＋ 引用依据</button></fieldset></div><button @click="unit">＋ 内容单元</button></details></template><EntityActions :record="r" generate/><div class="actions"><button :disabled="s.busy.value||s.generating.value" title="生成期间不能重复提交任务" @click="s.generate('clue',r.id)"><AppIcon name="ai" :size="14"/>重新生成此线索</button><button @click="s.remove(r)">删除线索</button></div></fieldset></article><article v-else><div class="empty">整理资料后即可生成线索，也可手动新建。</div></article></div>
<div v-if="folder" class="modal"><article><h2>分类：{{folder.name}}</h2><label>{{folder.root?'新子分类名称':'分类名称'}}<input v-model="folderName"></label><div v-if="!folder.root" class="actions"><small>父分类：{{s.p.value.workspace.folders.find((f:any)=>f.id===folderParent)?.name}}</small><button @click="picking={id:'f:'+folder.id,kind:'folder-form'}">选择父分类</button></div><div class="actions"><button @click="createFolder">新增子分类</button><button v-if="!folder.root" @click="updateFolder()">保存分类</button><button v-if="!folder.root" @click="updateFolder(true)">删除空分类</button><button @click="folder=null">关闭</button></div></article></div><div v-if="picking" class="modal"><article class="tree-picker"><h2>移动到分类</h2><ClueGraph mode="pick" :folders="s.p.value.workspace.folders" :clues="clues" :moving="picking.id" @destination="destination"/><button @click="picking=null">取消</button></article></div></template>
